INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('dee68c24-88a4-4696-a397-c1c4deedb937', '21feff02-016d-46e2-bb9d-c27495133b1b', '72. óra: Egyenes arányosság grafikonja', 'Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "dc1aa622-2c63-41b6-9518-7053ad3a0262", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "c87e4b24-943e-4391-b37f-4aa91737c8fa", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "a4f5046b-6cd2-4cc0-b008-2b55b2e9d8b2", "text": "Parabola", "isCorrect": false}, {"id": "eaafe429-ec3b-495b-b9b9-ce5760959f49", "text": "Körvonal", "isCorrect": false}, {"id": "78c9d3de-8435-4545-902d-6d016752c5cb", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "3e118d6a-6fa6-460d-ba4e-92d344b3f1f9", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "dcd65455-d6dc-43d0-b89b-09e22871c6af", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "aedf8d6d-d3f6-464c-b909-431193b32d99", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8eeeaa9f-c0fc-4849-897d-6269c4ed129f", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "f3888b8e-9bf0-4779-8621-a466b706bf8d", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "80cd5a09-0a76-4db1-b161-3735e4194c97", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "ce67448d-00d4-4f4f-8331-35774d71cde2", "text": "Igaz", "isCorrect": true}, {"id": "a25bda8e-552c-4d80-94a2-9278f98c00ef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e19cdf27-bb73-4551-b3ed-591d7a3e34f3", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "73dcca98-e262-4c7f-8ca0-af6b97ea1e19", "text": "Igaz", "isCorrect": true}, {"id": "1a3aacb5-84f2-43b9-a2c5-082532143148", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "283bf4c9-1df8-408e-b4eb-f61b4f1060b1", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "f2abda2d-da94-41b3-9fc8-682bc92b8f11", "text": "Igaz", "isCorrect": true}, {"id": "f201e557-ee91-40aa-b669-777bd631f047", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('b38d3ac6-583c-48e2-968d-53d19d569e15', '21feff02-016d-46e2-bb9d-c27495133b1b', '73. óra: Gyakorlóóra', 'Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "41478cc3-8cfb-4821-b746-71583ec79dc2", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "9dfa2e83-b42a-4d9f-9fed-5525e17f9c28", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "88f2573e-2484-45a5-a5f5-fcb6a120d7ef", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "9ac86621-1fb9-424f-a58f-3216fc07e28c", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "cd26f828-7141-4f13-9218-037720344da5", "text": "Igaz", "isCorrect": true}, {"id": "c285601f-192b-43c3-93ee-50e823ddd47f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "954ad3c1-51e0-47cc-a80c-9ca60f0250cc", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "1cb254e2-c51e-4d40-89d0-21291112d570", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "351c43dd-0d6d-4886-b74b-82a045b8da21", "text": "Igaz", "isCorrect": true}, {"id": "db44b502-b7ef-46b2-9550-400f658fad80", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9e96fba0-055d-4754-ade3-c26fe6d8d16b", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()),
('69cada4c-8e88-472b-a68f-fceceb5bf77c', '21feff02-016d-46e2-bb9d-c27495133b1b', '74. óra: Matematikai játékok', 'Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "214552a5-cccd-4188-96e2-19563b3554dd", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "28d4aba1-7c1b-4f0d-9093-a6a2781051c2", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "fada8f62-8d06-4b83-8bc4-d2dc83d02c80", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "3624b79d-e32d-4291-b772-463b0fed685e", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "13e899ab-88e7-4d78-986c-4c27797e4c73", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "1eaa91e0-1e7a-4a37-a377-67be97866798", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "f0070842-9884-4620-a6f8-4cc8d9a5ba73", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "2e791ce3-7442-4214-bd57-cfcab2192245", "text": "Igaz", "isCorrect": true}, {"id": "aa2a823d-8791-44b5-a794-610bab93fbeb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ea983231-053a-4c01-af06-c560632efa4f", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "6c2cad04-f934-45e7-93bd-ef795d52dca1", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "7cb329fe-3894-4208-8cb4-d310f4ccacaa", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "bfd9f7e4-5e03-4617-b859-5f03a26150b0", "text": "Igaz", "isCorrect": true}, {"id": "d4ef77fe-585e-4c10-b3f7-5f09765a89e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e638ae21-0ad8-4dd7-824b-55ed0f39d15e", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "bbc439d8-843c-4899-9323-fc03da9d186e", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "a4041b73-4413-4291-af5f-ecdac42d29f1", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "e577f7f3-b83f-4dbb-ad42-11e877061aa0", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "fa3538ba-442d-4cc0-86e4-16293e9d0fe8", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('03673fef-7130-4ea9-ae1c-97c58e9496c1', '21feff02-016d-46e2-bb9d-c27495133b1b', '75. óra: Szabályok, megfeleltetések', 'Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b5d3bcc0-e77f-4e21-90e0-44139d488062", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "daae8049-90fe-4497-85d2-43d4ace72acc", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "aa34ddd0-c23a-428e-8686-0399ea720d1e", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "8a567597-17ad-4946-902e-dae8fac7af29", "text": "Igaz", "isCorrect": true}, {"id": "bb1e3b95-5b81-434e-b107-de46b64db61d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6f8fdf63-611b-47f2-bba4-fc93faee95d6", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "ffd51794-2b94-488e-8d2e-4b8059435cba", "text": "Melyik sorozat szabálya a ''Hozzáadás 5-tel''?", "type": "multiple-choice", "options": [{"id": "c197501a-bf7b-45fd-bb28-ac60d71c73c5", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "60de0f49-00a5-41d8-bb74-c15ad2bca044", "text": "5, 25, 125", "isCorrect": false}, {"id": "b4d86757-3c39-4f4a-9f23-feb5d99eb05c", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "e28c25be-6a65-4000-aa06-28b72cad32eb", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "cb198c79-754b-4ebb-bde3-a7ea675d7af5", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "1433ff55-2bda-49b9-92e1-b2de510ce5e9", "text": "Igaz", "isCorrect": true}, {"id": "df2153b0-1967-42b8-9e8d-fa8736fc1126", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "794f25de-e68a-4946-943c-cebdb40fd321", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()),
('087498e3-0eb9-4a30-8292-74503db59583', '21feff02-016d-46e2-bb9d-c27495133b1b', '76. óra: Gyakorlóóra', 'Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "47bb5b48-c6fe-4c3b-a83c-bb0c393705b2", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "eeaa3215-33ae-4879-b1ae-ca9d587d9d7b", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "e6774a99-9a52-41db-9d10-271b7f0a6062", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "ed8e5f62-613e-40b1-b1cb-f3b19a37f65c", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "fa6e92cf-3804-4116-8aba-cd92d920315c", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "36c9fd94-2154-430b-a58c-b9fdd2db602d", "text": "Igaz", "isCorrect": true}, {"id": "2eb27baf-4821-43ab-a16b-7db80ca0a740", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "23baf82e-a508-490d-8a2c-7fb808998352", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "1199563c-b049-4552-bcfa-e67b74eeb82b", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "ecaf0d2a-1f3b-4e9b-8ed1-c78487c1dc31", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "d603cb6c-157e-46a2-9430-65a47464456b", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "f8da1c50-e0a7-41b5-83c2-d05d4f8dc5ec", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "d2453074-c426-4f01-9200-ba8ccd3d9cff", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "e8dfb988-890b-4564-ace9-ff366d9c8d60", "text": "Igaz", "isCorrect": true}, {"id": "9bf885f1-8906-4421-9b59-f07b31ffdad0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());